Here is the root cause:
The iavf driver's PTP clock registration did not provide a settime64 callback, leading to a NULL pointer dereference when ptp_clock_settime() attempted to invoke it.

Here is the patch:

+static int iavf_ptp_settime64(struct ptp_clock_info *info,
+			      const struct timespec64 *ts)
+{
+	return -EOPNOTSUPP;
+}
+
 /**
  * iavf_ptp_cache_phc_time - Cache PHC time for performing timestamp extension
  */
 static int iavf_ptp_register_clock(struct iavf_adapter *adapter)
 {
 	struct ptp_clock_info *ptp_info = &adapter->ptp.info;
 	struct device *dev = &adapter->pdev->dev;
 	struct ptp_clock *clock;

 	snprintf(ptp_info->name, sizeof(ptp_info->name), "%s-%s-clk",
 		 KBUILD_MODNAME, dev_name(dev));
 	ptp_info->owner = THIS_MODULE;
 	ptp_info->gettimex64 = iavf_ptp_gettimex64;
+	ptp_info->settime64 = iavf_ptp_settime64;
 	ptp_info->do_aux_work = iavf_ptp_do_aux_work;

 	clock = ptp_clock_register(ptp_info, dev);
 	if (IS_ERR(clock))
 		return PTR_ERR(clock);

 	adapter->ptp.clock = clock;

 	dev_dbg(&adapter->pdev->dev, "PTP clock %s registered\n",
 		adapter->ptp.info.name);

 	return 0;
 }



